`timescale 1ns/1ps
// log_lut.v -- 8-bit pixel -> 8-bit log intensity ROM (image generated by `python -m model.log_lut`).
// Registered read, 1 clock latency. Standalone module so Quartus infers a ROM (checklist 1.1).
module log_lut #(
    parameter INIT_FILE = "rtl/log_lut.hex"
) (
    input  wire       clk,
    input  wire [7:0] addr,
    output reg  [7:0] q
);
    reg [7:0] rom [0:255];
    initial $readmemh(INIT_FILE, rom);
    always @(posedge clk) q <= rom[addr];
endmodule
